def cols_out(n):
    if n["op"] in ("Scan", "Project"):
        return set(n["cols"])
    s = set()
    for c in n.get("children", []):
        s |= cols_out(c)
    return s


def push_down(n):
    kids = [push_down(c) for c in n.get("children", [])]
    m = dict(n)
    m["children"] = kids
    if m["op"] == "Filter" and kids and kids[0]["op"] == "Join":
        j = kids[0]
        for i, side in enumerate(j["children"]):
            if set(m["refs"]) <= cols_out(side):
                inner = dict(m)
                inner["children"] = [side]
                nj = dict(j)
                nj["children"] = list(j["children"])
                nj["children"][i] = inner
                return nj
    return m


def prune(n, need):
    m = dict(n)
    if n["op"] == "Scan":
        m["cols"] = [c for c in n["cols"] if c in need]
        return m
    if n["op"] == "Project":
        keep = [c for c in n["cols"] if c in need]
        m["cols"] = keep
        m["children"] = [prune(n.get("children", [])[0], set(keep))]
        return m
    if n["op"] == "Filter":
        m["children"] = [prune(n.get("children", [])[0], need | set(n["refs"]))]
        return m
    if n["op"] == "Join":
        both = need | {n["key"]}
        m["children"] = [prune(n.get("children", [])[0], both), prune(n.get("children", [])[1], both)]
        return m
    if n["op"] == "Aggregate":
        m["children"] = [prune(n.get("children", [])[0], set(n["group"]) | set(n["funcs"]))]
        return m
    m["children"] = [prune(c, need) for c in n.get("children", [])]
    return m


def scans(n, acc=None):
    if acc is None:
        acc = []
    if n["op"] == "Scan":
        acc.append(n)
    for c in n.get("children", []):
        scans(c, acc)
    return acc


PLAN = {
    "op": "Aggregate", "group": ["city"], "funcs": ["amount"],
    "children": [{
        "op": "Filter", "pred": "city='bj'", "refs": ["city"], "det": True,
        "children": [{
            "op": "Join", "key": "uid",
            "children": [
                {"op": "Project", "cols": ["uid", "amount"], "children": [
                    {"op": "Scan", "name": "orders",
                     "cols": ["id", "uid", "dept", "amount", "ts"], "rows": 1000000}]},
                {"op": "Project", "cols": ["uid", "city"], "children": [
                    {"op": "Scan", "name": "users",
                     "cols": ["uid", "city", "age"], "rows": 100000}]},
            ]}]}]}

before = {s["name"]: len(s["cols"]) for s in scans(PLAN)}
pushed = push_down(PLAN)
optimized = prune(pushed, {"city", "amount"})
after = {s["name"]: s["cols"] for s in scans(optimized)}

print("orders:", before["orders"], "列 ->", len(after["orders"]), "列", after["orders"])
print("users:", before["users"], "列 ->", len(after["users"]), "列", after["users"])
print("谓词已下推到 users 侧:", pushed["children"][0]["children"][1]["op"] == "Filter")
print("列裁剪生效:", len(after["orders"]) < before["orders"] and len(after["users"]) < before["users"])
